/**
 * What this file does:
 * Provides the single write path for audit events generated by domain services.
 * What calls it:
 * `src/services/participantService.ts`, `src/services/visitService.ts`, and `src/services/safetyEventService.ts`.
 * What it calls:
 * `src/repositories/auditRepository.ts`.
 * One thing a junior engineer would likely get wrong when writing something similar:
 * Logging audit entries ad hoc in routes so some write paths are never captured.
 */
import { auditRepository } from "@/repositories/auditRepository";

export const auditService = {
  async record(event: {
    entityType: string;
    entityId: string;
    action: string;
    actorUserId: string;
    participantId: string | null;
    metadataJson: Record<string, unknown>;
  }) {
    return auditRepository.create({
      ...event,
      occurredAt: new Date().toISOString()
    });
  }
};

// ⚠️ SENIOR NOTE: A single audit write helper makes it much easier to later enforce
// consistent metadata, redact sensitive fields, or fan out to an external ledger.
